extern u_int WAVE_ScheduleTypeMax;

void WAVE_AddToSchedule(char id, const stringx &typestr, const stringx &breakstr,
	const stringx &wdstr, float scale, float duration);
static void WAVE_Load(u_int type);

__asm__(".equ WAVE_ScheduleTypeMax, 0x004846CC");
__asm__(".equ __7stringxPCci, 0x0034D438");
__asm__(".equ _$_7stringx, 0x0034D6E0");
__asm__(".equ WAVE_AddToSchedule__FcRC7stringxN21ff, 0x00377840");
__asm__(".equ WAVE_Load__FUi, 0x003737A8");

static void WAVE_LoadAll(void)
{
	if (WAVE_ScheduleTypeMax == 0)
	{
		WAVE_AddToSchedule('B', "default", "default", "default", 1, 60);
	}
	for (u_int i = 0; i < WAVE_ScheduleTypeMax; ++i)
	{
		WAVE_Load(i);
	}
}
